// 本試験対策（学校別）四天王寺学園・動く図解。キーは問題ID（data/honshiken_school_shitennoji.ts と同じ）。
// どの図も：状況 → 手がかり → 理由 → 計算 → 答え → 確かめ の順に7枚以上で動く。
// 座標は 320×240。上（y<142）に図、下の帯（y≧146）に式を置き、文字が図と重ならないようにしてある。
import type { DiagramElement, Figure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, pg, sc, show, band, fresh } from './diagram-kit';
import type { Slide } from './diagram-kit';

type E = DiagramElement;
const tx = (x: number, y: number, t: string, size = 12, color: string = C.ink, bold = true, anchor: 'start' | 'middle' | 'end' = 'middle'): E => lb(x, y, t, size, color, anchor, bold);
const NOFILL = 'rgba(255,255,255,0)';

// 下の帯：先頭文字で色が決まる（=緑 / ~赤 / *紫 / それ以外は青）。1行で先頭が「答え」なら大きく出す。
const tone = (s: string): [string, string, string] => {
  const c = s[0];
  if (c === '=') return [s.slice(1), C.green, FILL.green];
  if (c === '~') return [s.slice(1), C.red, FILL.red];
  if (c === '*') return [s.slice(1), C.purple, FILL.purple];
  return [s, C.blue, FILL.blue];
};
const B = (lines: string[]): E[] => {
  if (lines.length === 1) {
    const [t, col, fill] = tone(lines[0]);
    const big = t.startsWith('答え');
    return band(146, bx(20, big ? 158 : 166, 280, big ? 42 : 36, t, col, fill, big ? 18 : 15));
  }
  const h = lines.length === 2 ? 36 : 27;
  const gap = lines.length === 2 ? 40 : 30;
  const y0 = lines.length === 2 ? 154 : 150;
  return band(146, ...lines.map((s, i) => {
    const [t, col, fill] = tone(s);
    return bx(20, y0 + i * gap, 280, h, t, col, fill, lines.length === 2 ? 14 : 13);
  }));
};
const S = (note: string, lines: string[], add: E[] = []): Slide => ({ note, add: [...add, ...B(lines)] });
const SF = (note: string, lines: string[], draw: E[]): Slide => ({ note, add: [...fresh(...draw), ...B(lines)] });
const rows = (texts: string[], y0 = 34, dy = 24, size = 13, color: string = C.ink): E[] => texts.map((t, i) => tx(160, y0 + i * dy, t, size, color));
const arc = (cx: number, cy: number, r: number, a0: number, a1: number, n = 14): [number, number][] =>
  Array.from({ length: n + 1 }, (_, i) => { const a = a0 + ((a1 - a0) * i) / n; return [cx + r * Math.cos(a), cy + r * Math.sin(a)] as [number, number]; });
// 同じ半径の2つの円が重なる「レンズ形」の点列（画面座標）
const lens = (a: [number, number], b: [number, number], r: number): [number, number][] => {
  const dx = b[0] - a[0], dy = b[1] - a[1], d = Math.hypot(dx, dy);
  const mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2, h = Math.sqrt(r * r - (d / 2) * (d / 2));
  const P: [number, number] = [mx - (dy / d) * h, my + (dx / d) * h];
  const Q: [number, number] = [mx + (dy / d) * h, my - (dx / d) * h];
  const ang = (c: [number, number], p: [number, number]) => Math.atan2(p[1] - c[1], p[0] - c[0]);
  const sweep = (c: [number, number], p: [number, number], q: [number, number]) => {
    const a0 = ang(c, p); let a1 = ang(c, q);
    while (a1 - a0 > Math.PI) a1 -= 2 * Math.PI;
    while (a1 - a0 < -Math.PI) a1 += 2 * Math.PI;
    return arc(c[0], c[1], r, a0, a1);
  };
  return [...sweep(a, P, Q), ...sweep(b, Q, P)];
};

const figs: Record<string, Figure> = {};
const P = 'honshiken_school_shitennoji_';

